import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 3

def design(feats):
    # Remove near-duplicates based on correlation
    keep = set(feats.ids)
    corr_pairs = [(a,b) for a,b in [
        ('AMA9', 'YYZ3B'), ('JYBT5', 'CFBT2'), ('IBR14P', 'XQG5'),
        ('AMA9', 'IBR14P'), ('IBR14P', 'DKO12'), ('IBR14P', 'DZH3'),
        ('TPC2L', 'IBR14P'), ('IBR14P', 'YYZ3B'), ('IBR14P', 'CJML18'),
        ('KMJB2L', 'IBR14P'), ('QCE1', 'ZHKM14'), ('CKEP2P', 'ZNH15'),
        ('DKO12', 'YYZ3B'), ('KMJB2L', 'DZH3'), ('AMA9', 'DKO12'),
        ('TPC2L', 'XQG5'), ('AMA9', 'DZH3'), ('IDZY13P', 'HVYL1P'),
        ('DKO12', 'CJML18'), ('XQG5', 'DZH3')
    ] if a in keep and b in keep]

    for a, b in corr_pairs:
        keep.discard(b)  # Keep first, drop second

    # Get features with significant t-test (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if len(feats.x[feats.y==1, i]) > 0 and len(feats.x[feats.y==0, i]) > 0:
            try:
                t_stat = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic
                if abs(t_stat) > 2.0:
                    sig_features.append(fid)
            except:
                continue

    # Find strongest single feature
    best_single = None
    best_t = 0
    for fid in sig_features:
        i = feats.column(fid)
        if len(feats.x[feats.y==1, i]) > 0 and len(feats.x[feats.y==0, i]) > 0:
            try:
                t_stat = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic
                if abs(t_stat) > best_t:
                    best_t = abs(t_stat)
                    best_single = fid
            except:
                continue

    # Look for product terms
    candidates = []
    for i, fid_a in enumerate(sig_features):
        for j, fid_b in enumerate(sig_features[i+1:], i+1):
            if fid_a not in keep or fid_b not in keep:
                continue
            # Check if product creates better signal
            try:
                prod = feats.x[:, feats.column(fid_a)] * feats.x[:, feats.column(fid_b)]
                t_stat = stats.ttest_ind(prod[feats.y==1], prod[feats.y==0]).statistic
                if abs(t_stat) > 2.0:
                    candidates.append((abs(t_stat), fid_a, fid_b))
            except:
                continue

    # Sort by t-statistic and get top product
    candidates.sort(reverse=True)
    if candidates:
        _, a, b = candidates[0]
        return Design(
            drivers=(a, b),
            columns=(a, b),
            products=((a, b),),
            loadings={}
        )

    # Return single best feature if no strong product found
    if best_single:
        return Design(
            drivers=(best_single,),
            columns=(best_single,),
            products=(),
            loadings={}
        )

    # No mechanism
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

